function opportunityHref(pid,type,sort='recent',offset=0){return '#karaoke/browse?'+new URLSearchParams({profileOwner:pid,type,participation:'open',sort,offset});}
function opportunityCards(items,type){return items.length?'<div class="home-music-grid">'+items.map(t=>type==='duet'?playMusicCard(t,t.can_participate?'duet':null):playDubbingCard({...t,type:'dubbing',ownerName:t.owner_name||'',genres:JSON.parse(t.options_json||'{}').genres||[]}).replace('</article>','<a class="small-button play-record-link" href="#dubbing/'+esc(t.id)+'">'+(t.can_participate?'배역 확인 · 참여하기':'배역 확인')+'</a></article>')).join('')+'</div>':myEmpty('현재 참여 가능한 공개 작품이 없어요.');}
async function profileCollectionView(base,param,raw){
 const q=new URLSearchParams(raw.split('?')[1]||'');
 if(base==='karaoke'&&param==='browse'&&q.get('participation')==='open'){
  const pid=q.get('profileOwner'),type=q.get('type')==='dubbing'?'dubbing':'duet',sort=q.get('sort')==='plays'?'plays':'recent',offset=Number(q.get('offset'))||0;
  if(!pid)return {html:heading('프로필을 선택해주세요.')};
  const d=await api('/api/producers/'+encodeURIComponent(pid)+'/opportunities?'+new URLSearchParams({type,sort,offset}));
  return {tracks:type==='duet'?d.items:[],html:heading(esc(d.profile.name)+'의 참여 가능한 '+(type==='duet'?'듀엣':'더빙'))+'<div class="inline-actions"><a class="small-button" href="#producer/'+esc(pid)+'">프로필</a><span class="small-button" aria-current="true">참여 가능</span>'+[['recent','최신순'],['plays','재생순']].map(([k,l])=>'<a class="text-link" href="'+esc(opportunityHref(pid,type,k))+'" '+(sort===k?'aria-current="true"':'')+'>'+l+'</a>').join('')+'</div>'+(type==='dubbing'&&sort==='plays'?'<p class="field-help">더빙은 재생 집계가 없어 최신순으로 표시해요.</p>':'')+opportunityCards(d.items,type)+(offset?'<a class="small-button" href="'+esc(opportunityHref(pid,type,sort,Math.max(0,offset-24)))+'">이전</a>':'')+(d.nextOffset!==null?'<a class="small-button" href="'+esc(opportunityHref(pid,type,sort,d.nextOffset))+'">더보기</a>':'')};
 }
 if(base==='producer-songs'){
  const sort=q.get('sort')==='plays'?'plays':'recent',offset=Number(q.get('offset'))||0,d=await api('/api/producers/'+encodeURIComponent(param)+'/originals?'+new URLSearchParams({sort,offset})),href=(s,o=0)=>'#producer-songs/'+encodeURIComponent(param)+'?'+new URLSearchParams({sort:s,offset:o});
  return {tracks:d.tracks,html:heading(esc(d.profile.name)+'의 제작곡')+'<div class="inline-actions"><a class="small-button" href="#producer/'+esc(param)+'">프로필</a>'+[['recent','최신순'],['plays','재생순']].map(([s,l])=>'<a class="text-link" href="'+href(s)+'" '+(s===sort?'aria-current="true"':'')+'>'+l+'</a>').join('')+'</div>'+list(d.tracks)+(offset?'<a class="small-button" href="'+href(sort,Math.max(0,offset-24))+'">이전</a>':'')+(d.nextOffset!==null?'<a class="small-button" href="'+href(sort,d.nextOffset)+'">더보기</a>':'')};
 }
 if(base==='profile-artists'){
  const d=await api('/api/producers/'+encodeURIComponent(param)+'?dashboard=1'),pins=await api('/api/producers/'+encodeURIComponent(param)+'/pinned-artists');
  return {html:heading(esc(d.profile.name)+'의 소속 아티스트')+'<p>고정한 아티스트 최대 3명을 프로필에 먼저 표시해요.</p><div class="profile-pins" data-pin-owner="'+esc(param)+'" data-pins="'+esc(JSON.stringify(pins.ids))+'">'+d.artists.map(a=>'<article class="mp-manage-row">'+portrait(a,'artist')+'<a href="#artist/'+esc(a.id)+'">'+esc(a.name)+'</a>'+(pins.can_manage?'<button class="small-button" data-pin-artist="'+esc(a.id)+'">'+(pins.ids.includes(a.id)?'고정 해제':'상위 고정')+'</button>'+(pins.ids.includes(a.id)?'<button class="small-button" data-pin-up="'+esc(a.id)+'" aria-label="'+esc(a.name)+' 위로 이동">위로</button>':''):'')+'</article>').join('')+'</div>'};
 }return null;
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-pin-artist],[data-pin-up]');if(!b)return;const host=b.closest('[data-pin-owner]'),ids=JSON.parse(host.dataset.pins),key=b.dataset.pinArtist||b.dataset.pinUp;if(b.dataset.pinUp){const i=ids.indexOf(key);if(i>0)[ids[i-1],ids[i]]=[ids[i],ids[i-1]];}else if(ids.includes(key))ids.splice(ids.indexOf(key),1);else if(ids.length===3){toast('최대 3명까지 고정할 수 있어요. 먼저 한 명을 해제해주세요.');return;}else ids.push(key);b.disabled=true;try{await api('/api/producers/'+host.dataset.pinOwner+'/pinned-artists','PUT',{ids});await render();}catch(err){toast(err.message);b.disabled=false;}});
